try {
    // Code that may throw an exception
    throw std::runtime_error("Example error");
} catch (const std::exception& e) {
    // Handler code
    std::cout << e.what();
} // Implementation notes: The compiler generates an exception handling table for the try block, which includes pointers to destructors for automatic variables in scope. For each throw, the runtime uses this table to unwind the stack, calling destructors (e.g., via operator delete for objects) before transferring control to the catch block.
